package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.time.LocalDate;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Current unresolved issues, grouped by actual document and reason rather than log attempts. */
@Service public class SupplychainOperations {
    @Resource WmsStore db;
    public static final Set<String> CODES=new LinkedHashSet<>(Arrays.asList("STOCK_DIFFERENCE","TRANSFER","PARCEL","RESTORE","SUPPLIER","REMAINING","RECLAIM","OVERDUE","DISPATCH","UNKNOWN","QUERY","RECEIPT","POSTING","CUTOFF","REVIEW","DIFFERENCE","RETURN","PROCESS"));
    private static class Part {String sql;List<Object> args=new ArrayList<>();Part(String sql,Object...args){this.sql=sql;this.args.addAll(Arrays.asList(args));}}
    public Map<String,Object> query(String c,Map<String,String> q){
        String number=text(q.get("number")),code=text(q.get("issue")),store=text(q.get("store"));require(number.length()<=128&&store.length()<=64&&(code.isEmpty()||CODES.contains(code)),"供应链待办筛选无效");int page=q.containsKey("pageNum")?Math.toIntExact(id(q.get("pageNum"))):1,size=q.containsKey("pageSize")?Math.toIntExact(id(q.get("pageSize"))):20;require(page>=1&&page<=10000&&size>=1&&size<=50,"每页最多50条");
        String from=text(q.get("from")),to=text(q.get("to"));if(from.isEmpty()&&to.isEmpty()&&number.isEmpty()){from=LocalDate.now().minusDays(90).toString();to=LocalDate.now().toString();}if(!from.isEmpty()||!to.isEmpty()){try{LocalDate a=LocalDate.parse(from),b=LocalDate.parse(to);require(!b.isBefore(a)&&!b.isAfter(a.plusDays(93)),"查询日期范围最多93天");to=b.plusDays(1).toString();}catch(java.time.format.DateTimeParseException invalid){throw new IllegalArgumentException("请完整选择有效日期");}}
        List<Part> parts=new ArrayList<>();
        parts.add(new Part("SELECT CONCAT('P:',p.id) issue_key,'OVERDUE' issue,'purchase' kind,p.id document_id,p.po_sn document_sn,p.id purchase_id,NULL receipt_id,NULL difference_id,p.po_sn,s.supplier_name,p.wms_simulation_code store_code,p.number_expected-p.number_actually quantity,'预计日期已过，采购仍未全部入库' reason,p.create_time,p.expected_date due_time FROM po_info p LEFT JOIN supplier_info s ON s.company_key=p.company_key AND s.supplier_sn=p.supplier_sn WHERE p.company_key=? AND p.po_state IN(2,3) AND p.expected_date<CURDATE() AND p.number_expected>p.number_actually",c));
        String join=" FROM wms_inbound_task a JOIN wms_tickets t ON t.company_key=a.company_code AND t.id=a.ticket_id JOIN no_tickets n ON n.company_key=a.company_code AND n.no_sn=t.relation_sn JOIN po_info p ON p.company_key=a.company_code AND p.po_sn=n.po_sn LEFT JOIN supplier_info s ON s.company_key=p.company_key AND s.supplier_sn=p.supplier_sn WHERE a.company_code=?";
        for(String[] rule:new String[][]{{"DISPATCH","a.dispatch_state='FAILED'","COALESCE(NULLIF(a.last_error,''),'仓库下发明确失败')"},{"UNKNOWN","a.dispatch_state IN('SENDING','UNKNOWN')","'原仓库受理结果待确认，须查询原单'"},{"QUERY","a.last_query_result IN('FAILED','UNKNOWN','TIMEOUT','NOT_FOUND','UNSUPPORTED')","a.query_message"},{"RECEIPT","a.warehouse_status IN('FULFILLED','CLOSED') AND a.receipt_state<>'COMPLETE'","'仓库状态已结束，实际收货明细尚未完整回传'"},{"POSTING","t.inventory_status=3","'存在入账失败明细，已成功部分不重复入账'"},{"CUTOFF","a.cancel_state IN('PENDING','UNKNOWN','REJECTED') OR n.cutoff_state IN('PROCESSING','WAIT_REVIEW')","COALESCE(NULLIF(a.last_error,''),'原截单申请尚待确认')"}})
            parts.add(new Part("SELECT CONCAT('I:"+rule[0]+":',t.id) issue_key,'"+rule[0]+"' issue,'receipt' kind,n.id document_id,n.no_sn document_sn,p.id purchase_id,n.id receipt_id,NULL difference_id,p.po_sn,s.supplier_name,t.wms_simulation_code store_code,NULL quantity,"+rule[2]+" reason,n.create_time,n.expected_callback_time due_time"+join+" AND ("+rule[1]+")",c));
        parts.add(new Part("SELECT CONCAT('D:',d.ticket_id,':',d.difference_kind) issue_key,'DIFFERENCE' issue,'receipt' kind,n.id document_id,n.no_sn document_sn,p.id purchase_id,n.id receipt_id,MIN(d.id) difference_id,p.po_sn,s.supplier_name,t.wms_simulation_code store_code,SUM(d.difference_quantity) quantity,CONCAT(d.difference_kind,'：',COUNT(*),'条待处理差异；',MAX(d.reason)) reason,MIN(n.create_time) create_time,n.expected_callback_time due_time FROM purchase_receipt_difference d JOIN wms_tickets t ON t.company_key=d.company_code AND t.id=d.ticket_id JOIN no_tickets n ON n.company_key=d.company_code AND n.no_sn=t.relation_sn JOIN po_info p ON p.company_key=d.company_code AND p.po_sn=n.po_sn LEFT JOIN supplier_info s ON s.company_key=p.company_key AND s.supplier_sn=p.supplier_sn WHERE d.company_code=? AND d.state IN('OPEN','WAITING') GROUP BY d.company_code,d.ticket_id,d.difference_kind,n.id,p.id,s.supplier_name,t.wms_simulation_code,n.expected_callback_time",c));
        parts.add(new Part("SELECT CONCAT('R:',r.ticket_id) issue_key,'REVIEW' issue,'receipt' kind,n.id document_id,n.no_sn document_sn,p.id purchase_id,n.id receipt_id,NULL difference_id,p.po_sn,s.supplier_name,t.wms_simulation_code store_code,NULL quantity,'截单后到货待核对，未确认部分尚未入账' reason,MIN(n.create_time) create_time,n.expected_callback_time due_time FROM wms_inbound_receipt_review r JOIN wms_tickets t ON t.company_key=r.company_code AND t.id=r.ticket_id JOIN no_tickets n ON n.company_key=r.company_code AND n.no_sn=t.relation_sn JOIN po_info p ON p.company_key=r.company_code AND p.po_sn=n.po_sn LEFT JOIN supplier_info s ON s.company_key=p.company_key AND s.supplier_sn=p.supplier_sn WHERE r.company_code=? AND r.state='WAIT_REVIEW' GROUP BY r.company_code,r.ticket_id,n.id,p.id,s.supplier_name,t.wms_simulation_code,n.expected_callback_time",c));
        parts.add(new Part("SELECT CONCAT('PR:',p.id) issue_key,'PROCESS' issue,'process' kind,p.id document_id,p.process_sn document_sn,NULL purchase_id,NULL receipt_id,NULL difference_id,'' po_sn,'' supplier_name,p.store_code,NULL quantity,COALESCE(NULLIF(p.last_error,''),'加工仓库交互或结果待核对') reason,p.create_time,NULL due_time FROM wms_process_order p WHERE p.company_code=? AND p.state NOT IN('COMPLETED','STOPPED') AND (p.dispatch_state IN('FAILED','UNKNOWN') OR p.last_error<>'')",c));
        parts.add(new Part("SELECT CONCAT('O:',d.id) issue_key,'DISPATCH' issue,'ticket' kind,d.ticket_id document_id,t.sn document_sn,NULL purchase_id,NULL receipt_id,NULL difference_id,'' po_sn,'' supplier_name,d.store_code,NULL quantity,COALESCE(NULLIF(d.last_error,''),'销售出库仓库结果待核对') reason,d.create_time,NULL due_time FROM wms_sales_outbound_document d JOIN wms_tickets t ON t.company_key=d.company_code AND t.id=d.ticket_id WHERE d.company_code=? AND d.dispatch_state IN('FAILED','UNKNOWN')",c));
        parts.add(new Part("SELECT CONCAT('A:',n.id) issue_key,'OVERDUE' issue,'receipt' kind,n.id document_id,n.no_sn document_sn,p.id purchase_id,n.id receipt_id,NULL difference_id,p.po_sn,s.supplier_name,n.wms_simulation_code store_code,NULL quantity,'本批预计到货日期已过，尚未最终确认收货' reason,n.create_time,n.expected_callback_time due_time FROM no_tickets n JOIN po_info p ON p.company_key=n.company_key AND p.po_sn=n.po_sn LEFT JOIN supplier_info s ON s.company_key=p.company_key AND s.supplier_sn=p.supplier_sn LEFT JOIN wms_inbound_task a ON a.company_code=n.company_key AND a.ticket_sn=n.relation_sn WHERE n.company_key=? AND n.no_state IN(2,3) AND n.expected_callback_time<CURDATE() AND COALESCE(a.receipt_state,'')<>'COMPLETE'",c));
        parts.add(new Part("SELECT CONCAT('AR:',d.id) issue_key,'RETURN' issue,'ticket' kind,d.ticket_id document_id,d.return_sn document_sn,NULL purchase_id,NULL receipt_id,NULL difference_id,'' po_sn,'' supplier_name,p.store_code,d.pending_quantity quantity,COALESCE(NULLIF(d.last_error,''),'共同退回仓库受理、实收归属或入账待核对') reason,d.create_time,NULL due_time FROM wms_shared_return_document d JOIN wms_shared_return_parcel p ON p.company_code=d.company_code AND p.id=d.parcel_id WHERE d.company_code=? AND (d.pending_receipt_count>0 OR d.dispatch_state IN('FAILED','UNKNOWN') OR d.cancel_state IN('PENDING','UNKNOWN','REJECTED') OR d.accepted_quantity>d.posted_quantity)",c));
        for(String prefix:Arrays.asList("wms_refund_return","wms_exchange_return"))parts.add(new Part("SELECT CONCAT('"+prefix+":',d.id) issue_key,'RETURN' issue,'ticket' kind,d.ticket_id document_id,d.return_sn document_sn,NULL purchase_id,NULL receipt_id,NULL difference_id,'' po_sn,'' supplier_name,d.store_code,NULL quantity,COALESCE(NULLIF(d.last_error,''),'独立退回仓库受理、实收或入账待核对') reason,d.create_time,NULL due_time FROM "+prefix+" d WHERE d.company_code=? AND d.ticket_id IS NOT NULL AND d.shared_member_id IS NULL AND d.return_sn NOT LIKE 'RSL%' AND (d.dispatch_state IN('FAILED','UNKNOWN') OR d.cancel_state IN('PENDING','UNKNOWN','REJECTED') OR d.accepted_quantity>d.posted_quantity OR EXISTS(SELECT 1 FROM "+prefix+"_review rv WHERE rv.company_code=d.company_code AND rv.task_id=d.id AND rv.state='WAIT_REVIEW'))",c));
        parts.add(new Part("SELECT CONCAT('VR:',r.id) issue_key,IF(r.receipt_review_pending=1,'REVIEW',IF(r.dispatch_state='FAILED','DISPATCH',IF(r.accepted_quantity>r.posted_quantity,'POSTING','UNKNOWN'))) issue,'purchaseReturn' kind,r.id document_id,r.return_sn document_sn,r.purchase_id,NULL receipt_id,NULL difference_id,r.po_sn,r.supplier_name,r.store_code,r.quantity-r.posted_quantity quantity,COALESCE(NULLIF(r.last_error,''),'采购退仓出库或库存结果待核对') reason,r.create_time,NULL due_time FROM purchase_return r WHERE r.company_code=? AND r.state NOT IN('DRAFT','CANCELED','COMPLETED') AND (r.last_error<>'' OR r.receipt_review_pending=1 OR r.dispatch_state IN('UNKNOWN','FAILED') OR r.accepted_quantity>r.posted_quantity)",c));
        parts.add(new Part("SELECT CONCAT('VRS:',r.id) issue_key,'REMAINING' issue,'purchaseReturn' kind,r.id document_id,r.return_sn document_sn,r.purchase_id,NULL receipt_id,NULL difference_id,r.po_sn,r.supplier_name,r.store_code,r.quantity-r.accepted_quantity quantity,'仓库最终短出，未出库数量仍占用，请选择结束或继续退仓' reason,r.create_time,NULL due_time FROM purchase_return r WHERE r.company_code=? AND r.state='APPROVED' AND r.receipt_final=1 AND r.quantity>r.accepted_quantity AND r.accepted_quantity=r.posted_quantity AND r.receipt_review_pending=0",c));
        parts.add(new Part("SELECT CONCAT('VRP:',r.id) issue_key,'PARCEL' issue,'purchaseReturn' kind,r.id document_id,r.return_sn document_sn,r.purchase_id,NULL receipt_id,NULL difference_id,r.po_sn,r.supplier_name,r.store_code,NULL quantity,'采购退仓包裹商品尚未补齐或原来源待核对；头部运单不能替代装箱明细，请在原CGT查看各次执行和包裹' reason,r.create_time,NULL due_time FROM purchase_return r WHERE r.company_code=? AND r.fulfillment_model=2 AND r.accepted_quantity>0 AND (EXISTS(SELECT 1 FROM purchase_return_parcel p WHERE p.company_code=r.company_code AND p.return_id=r.id AND p.content_state<>'MAPPED') OR EXISTS(SELECT 1 FROM purchase_return_execution e WHERE e.company_code=r.company_code AND e.return_id=r.id AND e.accepted_quantity>0 AND NOT EXISTS(SELECT 1 FROM purchase_return_parcel p WHERE p.company_code=e.company_code AND p.execution_id=e.id)))",c));
        parts.add(new Part("SELECT CONCAT('VRR:',r.id) issue_key,'RESTORE' issue,'purchaseReturn' kind,r.id document_id,r.return_sn document_sn,r.purchase_id,NULL receipt_id,NULL difference_id,r.po_sn,r.supplier_name,r.store_code,r.quantity-r.posted_quantity quantity,'已释放余量的同单恢复申请待审核，须重新校验原来源额度及可用库存，不直接下发仓库' reason,r.create_time,NULL due_time FROM purchase_return r WHERE r.company_code=? AND r.fulfillment_model=2 AND EXISTS(SELECT 1 FROM purchase_return_execution_request x WHERE x.company_code=r.company_code AND x.return_id=r.id AND x.state='REVIEW' AND x.kind='RESTORE')",c));
        parts.add(new Part("SELECT CONCAT('VRV:',r.id) issue_key,'SUPPLIER' issue,'purchaseReturn' kind,r.id document_id,r.return_sn document_sn,r.purchase_id,NULL receipt_id,NULL difference_id,r.po_sn,r.supplier_name,r.store_code,NULL quantity,'采购退仓已有实际出库，供应商商品接受或拒收尚未全部确认；物流签收不代表商品验收' reason,r.create_time,NULL due_time FROM purchase_return r WHERE r.company_code=? AND r.fulfillment_model=2 AND EXISTS(SELECT 1 FROM purchase_return_line l WHERE l.company_code=r.company_code AND l.return_id=r.id AND l.posted_quantity>l.supplier_received_quantity+l.supplier_refused_quantity)",c));
        parts.add(new Part("SELECT CONCAT('VRC:',h.id) issue_key,'RECLAIM' issue,'purchaseReclaim' kind,h.id document_id,h.reclaim_sn document_sn,r.purchase_id,NULL receipt_id,NULL difference_id,r.po_sn,r.supplier_name,h.store_code,h.quantity-h.posted_quantity quantity,COALESCE(NULLIF(h.last_error,''),'拒收收回仓库实收、短收或入账待处理') reason,h.create_time,NULL due_time FROM purchase_return_reclaim h JOIN purchase_return r ON r.company_code=h.company_code AND r.id=h.return_id WHERE h.company_code=? AND h.state IN('ACTIVE','CANCELING') AND (h.last_error<>'' OR h.dispatch_state IN('FAILED','UNKNOWN') OR h.accepted_quantity>h.posted_quantity OR h.receipt_final=1 OR h.state='CANCELING')",c));
        parts.add(new Part("SELECT CONCAT('DZ:',d.id) issue_key,'STOCK_DIFFERENCE' issue,'reconciliation' kind,d.id document_id,d.document_sn,NULL purchase_id,NULL receipt_id,NULL difference_id,'' po_sn,'' supplier_name,d.store_code,NULL quantity,IF(d.state='FAILED',d.last_error,CONCAT('实物不符',d.difference_count,'行，字段或冻结待核查',d.attention_count,'行，查询失败',d.failed_count,'种商品；请查看快照和待入账证据')) reason,d.create_time,NULL due_time FROM warehouse_reconciliation d WHERE d.company_code=? AND d.parent_id=0 AND (d.state IN('FAILED','PARTIAL') OR (d.state='COMPLETED' AND (d.difference_count>0 OR d.attention_count>0))) AND NOT EXISTS(SELECT 1 FROM warehouse_reconciliation newer WHERE newer.company_code=d.company_code AND newer.scope_hash=d.scope_hash AND newer.state='COMPLETED' AND newer.id>d.id) AND NOT EXISTS(SELECT 1 FROM warehouse_stock_adjustment a WHERE a.company_code=d.company_code AND a.reconciliation_id=d.id AND a.state='POSTED')",c));
        parts.add(new Part("SELECT CONCAT('DB:',d.id) issue_key,'TRANSFER' issue,'transfer' kind,d.id document_id,d.document_sn,NULL purchase_id,NULL receipt_id,NULL difference_id,'' po_sn,'' supplier_name,d.source_store store_code,NULL quantity,COALESCE(NULLIF(d.last_error,''),'调拨在途超过3天或两侧最终短收，请核对原批次及物流') reason,d.create_time,NULL due_time FROM warehouse_transfer d WHERE d.company_code=? AND d.state NOT IN('DRAFT','COMPLETED') AND (d.last_error<>'' OR EXISTS(SELECT 1 FROM warehouse_transfer_execution e WHERE e.company_code=d.company_code AND e.transfer_id=d.id AND (e.review_pending=1 OR e.dispatch_state IN('FAILED','UNKNOWN') OR (e.side='IN' AND e.receipt_final=1))) OR (d.create_time<DATE_SUB(NOW(),INTERVAL 3 DAY) AND EXISTS(SELECT 1 FROM warehouse_transfer_line l WHERE l.company_code=d.company_code AND l.transfer_id=d.id AND l.out_quantity>l.in_quantity+l.recovered_quantity)))",c));
        List<String> selects=new ArrayList<>();List<Object> args=new ArrayList<>();for(Part part:parts){selects.add("SELECT * FROM ("+part.sql+") current_issue WHERE 1=1"+(!number.isEmpty()?" AND (document_sn=? OR po_sn=? OR EXISTS(SELECT 1 FROM wms_tickets lookup WHERE lookup.company_key=? AND lookup.sn=? AND lookup.relation_sn=current_issue.document_sn))":"")+(!store.isEmpty()?" AND store_code=?":"")+(!from.isEmpty()?" AND create_time>=? AND create_time<?":""));args.addAll(part.args);if(!number.isEmpty()){args.add(number);args.add(number);args.add(c);args.add(number);}if(!store.isEmpty())args.add(store);if(!from.isEmpty()){args.add(from);args.add(to);}}
        String union=String.join(" UNION ALL ",selects);Map<String,Long> counts=new LinkedHashMap<>();counts.put("",0L);for(String k:CODES)counts.put(k,0L);for(Map<String,Object> row:db.jdbc.queryForList("SELECT issue,COUNT(*) count FROM ("+union+") all_issues GROUP BY issue",args.toArray())){long count=id(row.get("count"));counts.put(text(row.get("issue")),count);counts.put("",counts.get("")+count);}
        String sql="SELECT * FROM ("+union+") all_issues";if(!code.isEmpty()){sql+=" WHERE issue=?";args.add(code);}args.add(size);args.add((page-1)*size);List<Map<String,Object>> rows=db.jdbc.queryForList(sql+" ORDER BY create_time DESC,issue_key LIMIT ? OFFSET ?",args.toArray());for(Map<String,Object> row:rows)ReturnQueryWarehouse.formatTimes(row);return map("rows",rows,"total",counts.get(code),"counts",counts);
    }
}
